#include <bits/stdc++.h>
using namespace std;

struct FlowNetwork {
    struct Edge {
        int from, to;
        long long flow, capacity;
    };
    int source, sink;
    vector<Edge> edges;
    vector<int> adj[7100];
    int level[7100], ptr[7100], visited[7100];

    void reset() {
        edges.clear();
        for (int i = 0; i < 7100; ++i) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, long long cap) {
        edges.push_back({u, v, 0, cap});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(visited, 0, sizeof(visited));
        memset(level, 0, sizeof(level));
        queue<int> q;
        q.push(source);
        visited[source] = 1;
        level[source] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &idx : adj[u]) {
                auto &e = edges[idx];
                int v = e.to;
                if (!visited[v] && e.capacity > e.flow) {
                    level[v] = level[u] + 1;
                    q.push(v);
                    visited[v] = 1;
                }
            }
        }
        return visited[sink];
    }

    long long sendFlow(int u, long long flow) {
        if (u == sink || flow == 0) return flow;
        long long totalSent = 0;
        for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            auto &e = edges[adj[u][i]];
            if (level[u] + 1 == level[e.to]) {
                long long pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[u][i] ^ 1].flow -= pushed;
                    totalSent += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return totalSent;
    }

    long long maxFlow() {
        long long totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < 7100; ++i) ptr[i] = 0;
            totalFlow += sendFlow(source, LLONG_MAX);
        }
        return totalFlow;
    }
};

FlowNetwork network;
char maze1[14][14], maze2[14][14];
bool visitedCells[14][14];
int distMap[14][14];
int n;
int targetNodes[103];

void performBFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; ++i)
        for (int j = 0; j < 14; ++j)
            distMap[i][j] = 111;
    distMap[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visitedCells[cx][cy]) continue;
        visitedCells[cx][cy] = true;
        distMap[cx][cy] = d;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = cx + dx[dir], ny = cy + dy[dir];
            if (nx <= 0 || nx > n || ny <= 0 || ny > n || visitedCells[nx][ny] || maze1[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, d + 1});
        }
    }
}

int getIdx(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    int t, i, j, k;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; ++i) scanf("%s", maze1[i] + 1);
    for (i = 1; i <= n; ++i) scanf("%s", maze2[i] + 1);
    network.source = 0; network.sink = 7099;
    int startX = 0, startY = 0;
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (maze1[i][j] == 'Z') {
                startX = i; startY = j; break;
            }
        }
    }
    for (i = 1; i <= n * n; ++i) targetNodes[i] = 7098 - (n * n - i);
    performBFS(startX, startY);
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (maze1[i][j] >= '0' && maze1[i][j] <= '9')
                network.addEdge(network.source, getIdx(0, i, j), maze1[i][j] - '0');
            if (maze2[i][j] >= '0' && maze2[i][j] <= '9')
                network.addEdge(targetNodes[getIdx(0, i, j)], network.sink, maze2[i][j] - '0');
            network.addEdge(getIdx(0, i, j), targetNodes[getIdx(0, i, j)], LLONG_MAX);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; ++i) {
        for (j = 1; j <= n; ++j) {
            for (k = 1; k <= n; ++k) {
                if (maze1[j][k] == 'Y' || maze1[j][k] == 'Z') continue;
                for (int l = 0; l < 4; ++l) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && maze1[tx][ty] != 'Y' && maze1[tx][ty] != 'Z') {
                        if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                            network.addEdge(getIdx(i - 1, tx, ty), getIdx(i, j, k), LLONG_MAX);
                        }
                    }
                }
                network.addEdge(getIdx(i, j, k), targetNodes[getIdx(0, j, k)], LLONG_MAX);
            }
        }
    }
    printf("%lld\n", network.maxFlow());
    return 0;
}
